/**
 * TJS Test Execution
 *
 * Handles transpile-time test execution, signature validation, and test utilities.
 */

import {
  maskLiterals,
  stripComments as sharedStripComments,
  matchingBrace,
  splitTopLevel,
  splitTopLevelTrimmed,
} from '../../strip-comments'
import { transformExtensionCalls } from '../parser'
import { installRuntime } from '../runtime'
import { expectFunction } from '../tests'
import type { ExtractedTest, ExtractedMock } from '../tests'
import { parseLiteralValue } from '../literal-value'

/**
 * A TJS example value, PARSED rather than executed.
 *
 * These sites used `new Function(\`return ${text}\`)()`, which ran the annotation with full
 * ambient authority at transpile time — `tjs check` on an untrusted `.tjs` executed it. See
 * `literal-value.ts` for the accepted grammar. Throws on refusal so the callers' existing
 * `catch` blocks, which already skipped an unreadable example, behave exactly as before.
 */
function __lit(text: string): any {
  const r = parseLiteralValue(text)
  if (!r.ok) throw new Error(`not a literal example: ${r.reason}`)
  return r.value
}

export interface TestResult {
  /** Test description */
  description: string
  /** Whether the test passed */
  passed: boolean
  /** Error message if failed */
  error?: string
  /** Whether this was an implicit signature test */
  isSignatureTest?: boolean
  /**
   * The test could not be *run* (e.g. it references a name TJS can't resolve at
   * build time — like an AJS atom — or the harness couldn't execute the module).
   * Inconclusive ≠ failed: it never blocks transpilation. Surfaced as a warning
   * (e.g. in the playground). See PRINCIPLES.md ("more, never illegal").
   */
  inconclusive?: boolean
  /** Source line number (1-indexed) where the test or error occurred */
  line?: number
  /** Source column number (1-indexed) */
  column?: number
}

function fuzzyEqual(a: unknown, b: unknown, epsilon = 1e-9): boolean {
  if (a === b) return true
  if (typeof a === 'number' && typeof b === 'number') {
    // Check if either is non-integer (float)
    if (!Number.isInteger(a) || !Number.isInteger(b)) {
      const diff = Math.abs(a - b)
      const maxAbs = Math.max(Math.abs(a), Math.abs(b), 1)
      return diff / maxAbs < epsilon
    }
  }
  return false
}

/**
 * Deep equality check with fuzzy float comparison.
 *
 * #21: pair-memoized — without the memo, shared-reference graphs (DAGs)
 * compared in O(2^depth) (~61s at depth 30) and distinct-but-cyclic graphs
 * recursed forever. A revisited pair is assumed equal (sound: any false
 * short-circuits every .every() to the top, so a memoized pair either proved
 * true or is still in progress higher in this stack). Lazily allocated —
 * primitive/flat compares never touch it. Injected into transpile-time test
 * harnesses as __deepEqual; four sibling copies share the invariant (tests.ts
 * expectFunction, runtime Is, emitted inline Is) — dag-safety.test.ts guards
 * them together.
 */
function deepEqual(a: unknown, b: unknown): boolean {
  let seen: WeakMap<object, WeakSet<object>> | null = null
  const go = (a: unknown, b: unknown): boolean => {
    if (a === b) return true
    // NaN === NaN is false in JS, but NaN should equal NaN in tests
    if (
      typeof a === 'number' &&
      typeof b === 'number' &&
      Number.isNaN(a) &&
      Number.isNaN(b)
    )
      return true
    if (fuzzyEqual(a, b)) return true
    if (a === null || b === null) return a === b
    if (a === undefined || b === undefined) return a === b
    if (typeof a !== typeof b) return false
    if (typeof a !== 'object') return false

    if (seen === null) seen = new WeakMap()
    let set = seen.get(a as object)
    if (set) {
      if (set.has(b as object)) return true
    } else {
      set = new WeakSet()
      seen.set(a as object, set)
    }
    set.add(b as object)

    if (Array.isArray(a) && Array.isArray(b)) {
      if (a.length !== b.length) return false
      return a.every((v, i) => go(v, b[i]))
    }

    if (Array.isArray(a) !== Array.isArray(b)) return false

    const keysA = Object.keys(a as object)
    const keysB = Object.keys(b as object)
    if (keysA.length !== keysB.length) return false
    return keysA.every((k) => go((a as any)[k], (b as any)[k]))
  }
  return go(a, b)
}

/**
 * Check if a value matches an expected type pattern (from example value)
 * Unlike deepEqual, this checks TYPE compatibility, not value equality.
 *
 * Example patterns:
 *   0 matches any number
 *   "" matches any string
 *   true matches any boolean
 *   null matches null
 *   [] matches any array
 *   [0] matches array of numbers
 *   {name: "", age: 0} matches object with string name and number age
 */
function typeMatches(
  actual: unknown,
  pattern: unknown,
  path = ''
): { matches: boolean; error?: string } {
  // null pattern matches null
  if (pattern === null) {
    if (actual === null) return { matches: true }
    return {
      matches: false,
      error: `Expected null at '${path}', got ${typeOf(actual)}`,
    }
  }

  // undefined pattern matches undefined
  if (pattern === undefined) {
    if (actual === undefined) return { matches: true }
    return {
      matches: false,
      error: `Expected undefined at '${path}', got ${typeOf(actual)}`,
    }
  }

  // Primitive types - check type only (used by :? runtime validation)
  if (typeof pattern === 'number') {
    if (typeof actual === 'number') return { matches: true }
    return {
      matches: false,
      error: `Expected number at '${path}', got ${typeOf(actual)}`,
    }
  }

  if (typeof pattern === 'string') {
    if (typeof actual === 'string') return { matches: true }
    return {
      matches: false,
      error: `Expected string at '${path}', got ${typeOf(actual)}`,
    }
  }

  if (typeof pattern === 'boolean') {
    if (typeof actual === 'boolean') return { matches: true }
    return {
      matches: false,
      error: `Expected boolean at '${path}', got ${typeOf(actual)}`,
    }
  }

  // Arrays
  if (Array.isArray(pattern)) {
    if (!Array.isArray(actual)) {
      return {
        matches: false,
        error: `Expected array at '${path}', got ${typeOf(actual)}`,
      }
    }
    // Empty array pattern matches any array
    if (pattern.length === 0) return { matches: true }
    // Non-empty array pattern: check each element against first pattern element
    const elementPattern = pattern[0]
    for (let i = 0; i < actual.length; i++) {
      const result = typeMatches(actual[i], elementPattern, `${path}[${i}]`)
      if (!result.matches) return result
    }
    return { matches: true }
  }

  // Objects
  if (typeof pattern === 'object' && pattern !== null) {
    if (
      typeof actual !== 'object' ||
      actual === null ||
      Array.isArray(actual)
    ) {
      return {
        matches: false,
        error: `Expected object at '${path}', got ${typeOf(actual)}`,
      }
    }
    // Check all pattern keys exist and match types
    for (const key of Object.keys(pattern)) {
      const keyPath = path ? `${path}.${key}` : key
      if (!(key in actual)) {
        return { matches: false, error: `Missing property '${keyPath}'` }
      }
      const result = typeMatches(
        (actual as any)[key],
        (pattern as any)[key],
        keyPath
      )
      if (!result.matches) return result
    }
    return { matches: true }
  }

  // Fallback: exact equality
  if (actual === pattern) return { matches: true }
  return { matches: false, error: `Type mismatch at '${path}'` }
}

/**
 * Get a human-readable type description
 */
function typeOf(v: unknown): string {
  if (v === null) return 'null'
  if (v === undefined) return 'undefined'
  if (Array.isArray(v)) return 'array'
  return typeof v
}

/**
 * Format a value for error messages - uses cleaner object notation
 * Multi-line for objects with 3+ properties
 *
 * #21: shared-reference-aware and depth-capped. The per-level fanout
 * truncation (8 entries / 3 items) never bounded DEPTH, so a `{a: n, b: n}`
 * DAG still expanded 2^depth — and `indent` is no proxy for depth (the 1-2
 * entry single-line path recurses without bumping it). Revisited objects
 * render as [shared] (collapses DAGs and true cycles), depth caps at
 * MAX_FORMAT_DEPTH, and the top-level result is clamped so no failure
 * message can allocate unboundedly. Injected into transpile-time harnesses
 * as __format.
 */
const MAX_FORMAT_DEPTH = 6
const MAX_FORMAT_LENGTH = 16384

function formatValue(
  v: unknown,
  indent = 0,
  depth = 0,
  seen?: WeakSet<object>
): string {
  const result = formatValueInner(v, indent, depth, seen)
  if (depth === 0 && result.length > MAX_FORMAT_LENGTH) {
    return result.slice(0, MAX_FORMAT_LENGTH) + '…[truncated]'
  }
  return result
}

function formatValueInner(
  v: unknown,
  indent: number,
  depth: number,
  seen?: WeakSet<object>
): string {
  if (v === null) return 'null'
  if (v === undefined) return 'undefined'
  if (typeof v === 'string') return JSON.stringify(v)
  if (typeof v === 'number') return String(v)
  if (typeof v === 'boolean') return String(v)
  if (Array.isArray(v)) {
    if (v.length === 0) return '[]'
    if (!seen) seen = new WeakSet()
    if (seen.has(v)) return '[shared]'
    seen.add(v)
    if (depth >= MAX_FORMAT_DEPTH) return '[…]'
    if (v.length <= 3)
      return `[${v
        .map((x) => formatValue(x, indent, depth + 1, seen))
        .join(', ')}]`
    return `[${v
      .slice(0, 3)
      .map((x) => formatValue(x, indent, depth + 1, seen))
      .join(', ')}, ...]`
  }
  if (typeof v === 'object') {
    const entries = Object.entries(v)
    if (entries.length === 0) return '{}'
    if (!seen) seen = new WeakSet()
    if (seen.has(v)) return '[shared]'
    seen.add(v)
    if (depth >= MAX_FORMAT_DEPTH) return '{…}'

    const formatKey = (k: string) =>
      /^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(k) ? k : JSON.stringify(k)

    // Single line for 1-2 properties
    if (entries.length <= 2) {
      const formatted = entries
        .map(
          ([k, val]) =>
            `${formatKey(k)}: ${formatValue(val, indent, depth + 1, seen)}`
        )
        .join(', ')
      return `{${formatted}}`
    }

    // Multi-line for 3+ properties
    const pad = '  '.repeat(indent + 1)
    const closePad = '  '.repeat(indent)
    const formatted = entries
      .slice(0, 8)
      .map(
        ([k, val]) =>
          `${pad}${formatKey(k)}: ${formatValue(
            val,
            indent + 1,
            depth + 1,
            seen
          )}`
      )
      .join(',\n')
    const suffix = entries.length > 8 ? `,\n${pad}...` : ''
    return `{\n${formatted}${suffix}\n${closePad}}`
  }
  return String(v)
}

/**
 * Strip comments from source code
 * Used to avoid matching code patterns inside comments
 */
function stripComments(code: string): string {
  // The shared, literal-aware stripper. This site wants comments GONE and literals INTACT
  // — the strings here are test DESCRIPTIONS, so blanking them erases the thing being
  // extracted — which is why neither masking view fitted and this function hand-rolled it
  // with two raw regexes for a while.
  //
  // That hand-roll carried the ASI bug's shape: a `//` inside a template literal
  // truncated the line. The same class, in the module-directive detectors, turned out to
  // cost 90 seconds of a 116-second transpile — which is what finally justified building
  // the primitive instead of documenting its absence.
  return sharedStripComments(code)
}

/**
 * Strip import/export syntax for test execution context
 * Tests run in new Function() which doesn't support ES modules
 *
 * Useful for:
 * - Running tests in new Function() context
 * - CLI test runners
 * - Bundler plugins that need to extract module code
 */
export function stripModuleSyntax(code: string): string {
  // Remove import statements (entire line)
  let result = code.replace(/^import\s+.*?from\s+['"][^'"]+['"];?\s*$/gm, '')
  result = result.replace(/^import\s+['"][^'"]+['"];?\s*$/gm, '')

  // Remove 'export ' keyword but keep the declaration
  result = result.replace(/^export\s+default\s+/gm, '')
  result = result.replace(/^export\s+/gm, '')

  // Strip top-level await (not inside functions) — incompatible with new Function()
  // Match lines that start with await or "const/let/var x = await ..."
  result = result.replace(
    /^(\s*)((?:const|let|var)\s+\w+\s*=\s*)?await\s+.+$/gm,
    '$1/* top-level await removed for test execution */'
  )

  return result
}

/**
 * Strip the __tjs runtime preamble from transpiled code
 * This is needed when injecting resolved imports into a test context
 * that already has its own __tjs stub
 *
 * Useful for:
 * - Combining multiple TJS modules into a single execution context
 * - Test runners that provide their own __tjs runtime
 * - Bundlers that need to deduplicate runtime setup
 */
export function stripTjsPreamble(code: string): string {
  // Remove the __tjs runtime setup line — `const __tjs = <installed runtime> ?? <inline
  // fallback>;`, always ONE line. This matched one literal spelling of it, which the emitter
  // stopped producing long ago, so it had silently stripped nothing; it now matches the
  // declaration, whatever its right-hand side (0.14.0, found when the ABI gate changed it).
  let result = code.replace(/^const __tjs = [^\n]*\n?/m, '')
  result = result.replace(/^const \{ [\w, ]+ \} = __tjs \?\? \{\};\n?/m, '')
  return result
}

/**
 * Build code to inject resolved imports into test execution context
 *
 * Takes a map of module specifier -> compiled code and returns code that
 * makes those exports available in the test scope.
 *
 * For example, if resolvedImports contains:
 *   { 'mymath': 'function add(a, b) { return a + b }\nadd.__tjs = {...}' }
 *
 * This will return code that evaluates that module and makes `add` available.
 */
function buildResolvedImportsCode(
  resolvedImports: Record<string, string>
): string {
  if (Object.keys(resolvedImports).length === 0) {
    return ''
  }

  const lines: string[] = []

  for (const [specifier, moduleCode] of Object.entries(resolvedImports)) {
    // Strip module syntax from the imported code too (it may have exports)
    const cleanCode = stripModuleSyntax(moduleCode)

    lines.push(`// Resolved import: ${specifier}`)
    lines.push(cleanCode)
  }

  return lines.join('\n')
}

/**
 * Parse a return type example that may contain `key = defaultValue` syntax.
 * Transforms `{ value: 0, error = '' }` into valid JS `{ value: 0, error: '' }`
 * and extracts the default values for optional keys.
 */
function parseReturnExample(
  str: string
): { pattern: unknown; defaults: Record<string, unknown> } | null {
  const defaults: Record<string, unknown> = {}

  // Only process objects that might contain = syntax
  const trimmed = str.trim()
  if (!trimmed.startsWith('{') || !trimmed.includes('=')) {
    try {
      return { pattern: __lit(str), defaults }
    } catch {
      return null
    }
  }

  // Transform top-level `key = value` to `key: value` and track defaults
  // Walk the string respecting nesting depth
  let transformed = ''
  let depth = 0
  let i = 0

  while (i < trimmed.length) {
    const ch = trimmed[i]

    if (ch === '{' || ch === '[' || ch === '(') {
      depth++
      transformed += ch
      i++
    } else if (ch === '}' || ch === ']' || ch === ')') {
      depth--
      transformed += ch
      i++
    } else if (ch === "'" || ch === '"' || ch === '`') {
      // Skip string literals
      const quote = ch
      transformed += ch
      i++
      while (i < trimmed.length && trimmed[i] !== quote) {
        if (trimmed[i] === '\\') {
          transformed += trimmed[i++]
        }
        transformed += trimmed[i++]
      }
      if (i < trimmed.length) {
        transformed += trimmed[i++]
      }
    } else if (depth === 1 && ch === '=') {
      // Top-level `key = value` — look back for the key name
      const beforeEq = transformed.slice(transformed.lastIndexOf('{') + 1)
      const lastSegment = beforeEq.split(',').pop() || ''
      const keyMatch = lastSegment.match(/\s*(\w+)\s*$/)
      if (keyMatch) {
        // Find the value after =
        let j = i + 1
        while (j < trimmed.length && /\s/.test(trimmed[j])) j++

        // Extract value (up to , or } at depth 1)
        let valStr = ''
        let valDepth = 0
        while (j < trimmed.length) {
          const vc = trimmed[j]
          if (vc === '{' || vc === '[' || vc === '(') valDepth++
          else if (vc === '}' || vc === ']' || vc === ')') {
            if (valDepth === 0) break
            valDepth--
          } else if (vc === ',' && valDepth === 0) break
          valStr += vc
          j++
        }

        try {
          defaults[keyMatch[1]] = __lit(valStr.trim())
        } catch {
          // Can't parse default, skip
        }

        // Replace = with : in output
        transformed += ':'
        i++
        continue
      }
      transformed += ch
      i++
    } else {
      transformed += ch
      i++
    }
  }

  try {
    return { pattern: __lit(transformed), defaults }
  } catch {
    return null
  }
}

/**
 * Info about a signature test (extracted but not yet executed)
 */
interface SignatureTestInfo {
  funcName: string
  args: unknown[]
  expected: unknown
  defaults?: Record<string, unknown>
  line: number
  isAsync?: boolean
  /** For class method tests: the class name */
  className?: string
  /** For class method tests: args to pass to the first constructor */
  constructorArgs?: unknown[]
}

/**
 * Extract signature test info from source without executing
 */
export function extractSignatureTestInfos(
  originalSource: string
): SignatureTestInfo[] {
  const infos: SignatureTestInfo[] = []

  // Strip comments to avoid matching functions inside doc comments/code examples
  const sourceWithoutComments = stripComments(originalSource)

  // Match function declarations with return type marker (: or :?)
  // Skip :! which means "don't test"
  // Pattern: [async] function name(params): returnExample {
  const funcRegex = /(async\s+)?function\s+(\w+)\s*\(([^)]*)\)\s*(:[?!]?)\s*/g

  let match
  while ((match = funcRegex.exec(sourceWithoutComments)) !== null) {
    const isAsync = !!match[1]
    const funcName = match[2]
    const paramsStr = match[3]
    const returnMarker = match[4]

    // Calculate line number from match position in stripped source
    const lineNumber = sourceWithoutComments
      .slice(0, match.index)
      .split('\n').length

    // :! means skip test
    if (returnMarker === ':!') continue

    // Extract return example - handle nested braces/brackets
    const afterMarker = sourceWithoutComments.slice(
      match.index + match[0].length
    )
    const returnExample = extractReturnExampleFromSource(afterMarker)
    if (!returnExample) continue

    // Extract parameter examples
    const paramExamples = extractParamExamples(paramsStr)
    if (paramsStr.trim() && paramExamples.length === 0) continue

    try {
      // Parse expected value (with optional default keys) and args
      const parsed = parseReturnExample(returnExample)
      if (!parsed) continue

      const args = paramExamples.map((p) => __lit(p))

      infos.push({
        funcName,
        args,
        expected: parsed.pattern,
        defaults:
          Object.keys(parsed.defaults).length > 0 ? parsed.defaults : undefined,
        line: lineNumber,
        isAsync,
      })
    } catch {
      // Skip if parsing fails - will be reported as error during execution
    }
  }

  // Extract class method signature tests
  // Find class declarations and their first constructor's params,
  // then find methods with return type markers (: or :?)
  const classRegex = /class\s+(\w+)(?:\s+extends\s+\w+)?\s*\{/g
  let classMatch
  while ((classMatch = classRegex.exec(sourceWithoutComments)) !== null) {
    const className = classMatch[1]
    const classBodyStart = classMatch.index + classMatch[0].length

    // Find the matching closing brace for the class body
    let braceDepth = 1
    let classBodyEnd = classBodyStart
    for (let i = classBodyStart; i < sourceWithoutComments.length; i++) {
      if (sourceWithoutComments[i] === '{') braceDepth++
      else if (sourceWithoutComments[i] === '}') {
        braceDepth--
        if (braceDepth === 0) {
          classBodyEnd = i
          break
        }
      }
    }
    const classBody = sourceWithoutComments.slice(classBodyStart, classBodyEnd)

    // Find the first constructor's params
    const ctorRegex = /constructor\s*\(([^)]*)\)/
    const ctorMatch = ctorRegex.exec(classBody)
    if (!ctorMatch) continue

    const ctorParamsStr = ctorMatch[1]
    const ctorParamExamples = extractParamExamples(ctorParamsStr)
    if (ctorParamsStr.trim() && ctorParamExamples.length === 0) continue

    let ctorArgs: unknown[]
    try {
      ctorArgs = ctorParamExamples.map((p) => __lit(p))
    } catch {
      continue
    }

    // Find methods with return type markers inside the class body
    const methodRegex = /(async\s+)?(\w+)\s*\(([^)]*)\)\s*(:[?!]?)\s*/g
    let methodMatch
    while ((methodMatch = methodRegex.exec(classBody)) !== null) {
      const methodName = methodMatch[2]
      // Skip constructors and special names
      if (methodName === 'constructor') continue

      const isAsync = !!methodMatch[1]
      const paramsStr = methodMatch[3]
      const returnMarker = methodMatch[4]

      if (returnMarker === ':!') continue

      // Calculate line number from position in original source
      const methodPosInSource = classBodyStart + methodMatch.index
      const lineNumber = sourceWithoutComments
        .slice(0, methodPosInSource)
        .split('\n').length

      const afterMarker = classBody.slice(
        methodMatch.index + methodMatch[0].length
      )
      const returnExample = extractReturnExampleFromSource(afterMarker)
      if (!returnExample) continue

      const paramExamples = extractParamExamples(paramsStr)
      if (paramsStr.trim() && paramExamples.length === 0) continue

      try {
        const parsed = parseReturnExample(returnExample)
        if (!parsed) continue

        const args = paramExamples.map((p) => __lit(p))

        infos.push({
          funcName: methodName,
          args,
          expected: parsed.pattern,
          defaults:
            Object.keys(parsed.defaults).length > 0
              ? parsed.defaults
              : undefined,
          line: lineNumber,
          isAsync,
          className,
          constructorArgs: ctorArgs,
        })
      } catch {
        // Skip if parsing fails
      }
    }
  }

  return infos
}

/**
 * Run all tests (explicit blocks + signature tests) in a single execution context
 * This executes the module only once, then runs all tests against that context
 */
export function runAllTests(
  tests: ExtractedTest[],
  mocks: ExtractedMock[],
  sigTestInfos: SignatureTestInfo[],
  transpiledCode: string,
  resolvedImports: Record<string, string> = {},
  extensions: Map<string, Set<string>> = new Map()
): TestResult[] {
  const results: TestResult[] = []

  // If no tests at all, return empty
  if (tests.length === 0 && sigTestInfos.length === 0) {
    return results
  }

  // Detect unresolved imports — imports in source that aren't in resolvedImports
  const importSpecifiers =
    transpiledCode.match(/^import\s+.*?from\s+['"]([^'"]+)['"];?\s*$/gm) || []
  const hasUnresolvedImports =
    importSpecifiers.length > 0 &&
    importSpecifiers.some((imp) => {
      const match = imp.match(/from\s+['"]([^'"]+)['"]/)
      return match && !(match[1] in resolvedImports)
    })

  // Strip import/export for test execution (can't use modules in new Function)
  const executableCode = stripModuleSyntax(transpiledCode)
  // Strip __tjs preamble - test context provides its own stub
  // Real runtime installed via installRuntime() — preamble finds it via globalThis.__tjs

  // Build resolved imports code - inject imported module code into execution context
  const importedCode = buildResolvedImportsCode(resolvedImports)

  // Build mock setup
  const mockSetup = mocks.map((m) => m.body).join('\n')

  // Test bodies may reference Is/IsNot/Eq/NotEq/TypeOf — these come from the
  // == / != / typeof source-level transforms applied to test bodies in js.ts.
  // The module's own destructuring may not include them (if the module never
  // uses ==), so each test block re-destructures into its own block scope.
  //
  // `__tjs_rt` is bound to the same object for the same reason: those transforms now emit
  // `__tjs_rt.Eq(…)` rather than a bare `Eq(…)` (see `../rt-namespace.ts`), and a test body
  // is executed HERE, not inside the emitted module, so it never sees the module's
  // preamble. Without this every `==` inside a `test` block died with
  // `__tjs_rt is not defined` — which is what the three footgun examples reported.
  //
  // Pointing it at the shared runtime keeps the existing behaviour exactly: test bodies
  // have always resolved these off `globalThis.__tjs` while the module body used the inline
  // stubs. That divergence is real and documented (`docs/type-identity.md`); this change is
  // not the place to close it.
  const testRuntimeImports =
    `const { Is, IsNot, Eq, NotEq, TypeOf } = globalThis.__tjs ?? {};` +
    `const __tjs_rt = globalThis.__tjs ?? {};`

  // Build test execution code that runs all tests in sequence
  const testBodies = tests
    .map((t, i) => {
      // Extension calls were already rewritten in `js.ts` (with the other test-body
      // transforms), so the runner `tjs()` returns has them too. `extensions` is kept for
      // callers that pass raw bodies.
      const body =
        extensions.size > 0 && !t.extensionsRewritten
          ? transformExtensionCalls(t.body, extensions)
          : t.body
      return `
    // Test ${i}: ${t.description}
    try {
      ${testRuntimeImports}
      ${body}
      __testResults.push({ idx: ${i}, passed: true });
    } catch (e) {
      __testResults.push({ idx: ${i}, passed: false, isRef: e instanceof ReferenceError, error: e.message || String(e) });
    }
  `
    })
    .join('\n')

  // Filter out async functions — can't be tested synchronously at transpile time
  // Users should test async functions with explicit test blocks instead
  const syncSigTestInfos = sigTestInfos.filter((info) => !info.isAsync)
  const asyncSigTestInfos = sigTestInfos.filter((info) => info.isAsync)

  // Build signature test execution code
  const sigTestBodies = syncSigTestInfos
    .map((info, i) => {
      const testLabel = info.className
        ? `${info.className}.${info.funcName}`
        : info.funcName
      const callExpr = info.className
        ? `new ${info.className}(${(info.constructorArgs || [])
            .map(toSourceLiteral)
            .join(', ')}).${info.funcName}(${info.args
            .map(toSourceLiteral)
            .join(', ')})`
        : `${info.funcName}(${info.args.map(toSourceLiteral).join(', ')})`
      return `
    // Signature test ${i}: ${testLabel}
    try {
      let __actual = ${callExpr};
      const __expected = ${toSourceLiteral(info.expected)};${
        info.defaults
          ? `
      const __defaults = ${toSourceLiteral(info.defaults)};
      if (typeof __actual === 'object' && __actual !== null) __actual = Object.assign({}, __defaults, __actual);`
          : ''
      }
      if (__deepEqual(__actual, __expected)) {
        __sigTestResults.push({ idx: ${i}, passed: true });
      } else {
        __sigTestResults.push({ idx: ${i}, passed: false, error: 'Expected ' + __format(__expected) + ' at \\'${testLabel}\\', got ' + __format(__actual) });
      }
    } catch (e) {
      // The function threw on its example inputs — the example couldn't be
      // *evaluated* (e.g. it calls an atom that doesn't exist at build time).
      // That's inconclusive, not a mismatch. Never block transpilation on it.
      __sigTestResults.push({ idx: ${i}, passed: false, threw: true, error: e.message || String(e) });
    }
  `
    })
    .join('\n')

  // Install real TJS runtime for test execution
  installRuntime()

  const tjsStub = `
    const __saved_tjs = globalThis.__tjs;
  `
  const tjsRestore = `globalThis.__tjs = __saved_tjs;`

  // Combined test code - execute module ONCE, then run all tests
  const testCode = `
    ${tjsStub}
    const __testResults = [];
    const __sigTestResults = [];
    try {
      // Test assertions
      function assert(condition, message) {
        if (!condition) throw new Error(message || 'Assertion failed')
      }

      // THE shared expect, injected from ../tests -- not a copy.
      //
      // (No backticks in this comment: it lives inside a template literal, and one would
      // close it. The comment about literal-awareness being hard, defeated by a literal.)
      //
      // This used to be a near-duplicate, and the two drifted in opposite directions: that
      // one had toThrow and no toBeNaN, this one toBeNaN and no toThrow. Which matchers a
      // user got depended on which entry point ran their test, from source that cannot
      // tell them apart -- "tjs test file.tjs" died with "expect(...).toThrow is not a
      // function" on a test that passed in the playground. docs.ts documents every
      // matcher, so both halves of the divergence were documented as working.
      //
      // It defines its own deepEqual/format (memoized and output-capped, #21), so the
      // injected __deepEqual/__format below serve the signature-test path.
      ${expectFunction}

      // Inject resolved imports first (they may be dependencies)
      ${importedCode}

      // Execute the module code ONCE
      ${executableCode}
      ${mockSetup}

      // Run explicit test blocks
      ${testBodies}

      // Run signature tests
      ${sigTestBodies}

    } finally {
      ${tjsRestore}
    }
    return { testResults: __testResults, sigTestResults: __sigTestResults };
  `

  try {
    // Execute all tests
    const fn = new Function(
      '__deepEqual',
      '__format',
      '__typeMatches',
      testCode
    )
    const { testResults: blockResults, sigTestResults } = fn(
      deepEqual,
      formatValue,
      typeMatches
    )

    // Map block test results. A block test that threw a ReferenceError
    // couldn't *run* (it names something TJS can't resolve at build time, e.g.
    // an AJS atom) → inconclusive, not failed. An assertion failure (plain
    // Error from expect()) is a genuine failure.
    for (const r of blockResults) {
      const test = tests[r.idx]
      const inconclusive =
        !r.passed &&
        (r.isRef ||
          (hasUnresolvedImports && r.error && /is not defined$/.test(r.error)))
      results.push({
        description: test.description,
        passed: r.passed,
        inconclusive: inconclusive || undefined,
        error: r.error,
        line: test.line,
      })
    }

    // Map signature test results. A test that *threw* (couldn't evaluate the
    // example) is inconclusive; only a clean value-mismatch is a failure.
    for (const r of sigTestResults) {
      const info = syncSigTestInfos[r.idx]
      const inconclusive =
        !r.passed &&
        (r.threw ||
          (hasUnresolvedImports && r.error && /is not defined$/.test(r.error)))
      const label = info.className
        ? `${info.className}.${info.funcName}`
        : info.funcName
      results.push({
        description: `${label} signature example`,
        passed: r.passed,
        inconclusive: inconclusive || undefined,
        error: r.error,
        isSignatureTest: true,
        line: info.line,
      })
    }
  } catch (e: any) {
    // The whole module failed to execute, so NO test could run — every result
    // here is inconclusive, never a failure. Making transpilation fail because
    // an auto-generated test harness couldn't execute the module would turn
    // legal code illegal (e.g. a module referencing AJS atoms, or — an edge —
    // two top-level functions on one line). See PRINCIPLES.md.
    //
    // No line is attributed: the error came from module-level execution, not a
    // specific function, and mis-attributing it would point the editor at the
    // wrong site. The message is preserved as a warning on each result.
    const note = `Module could not be executed for testing: ${e.message}`
    for (const test of tests) {
      results.push({
        description: test.description,
        passed: false,
        inconclusive: true,
        error: note,
      })
    }
    for (const info of syncSigTestInfos) {
      const label = info.className
        ? `${info.className}.${info.funcName}`
        : info.funcName
      results.push({
        description: `${label} signature example`,
        passed: false,
        inconclusive: true,
        error: note,
        isSignatureTest: true,
      })
    }
  }

  // Add skipped results for async signature tests
  for (const info of asyncSigTestInfos) {
    const label = info.className
      ? `${info.className}.${info.funcName}`
      : info.funcName
    results.push({
      description: `${label} signature example`,
      passed: true,
      isSignatureTest: true,
      line: info.line,
    })
  }

  return results
}

/**
 * Evaluate an ObjectExpression AST node to a plain object
 */
function evalObjectExpression(node: any): Record<string, unknown> {
  const result: Record<string, unknown> = {}
  for (const prop of node.properties) {
    if (prop.type === 'Property' && prop.key) {
      const key =
        prop.key.type === 'Identifier' ? prop.key.name : prop.key.value
      if (prop.value.type === 'Literal') {
        result[key] = prop.value.value
      } else if (prop.value.type === 'ObjectExpression') {
        result[key] = evalObjectExpression(prop.value)
      } else if (prop.value.type === 'ArrayExpression') {
        result[key] = evalArrayExpression(prop.value)
      } else {
        throw new Error('Unsupported value type')
      }
    }
  }
  return result
}

/**
 * Evaluate an ArrayExpression AST node to an array
 */
function evalArrayExpression(node: any): unknown[] {
  const result: unknown[] = []
  for (const elem of node.elements) {
    if (elem.type === 'Literal') {
      result.push(elem.value)
    } else if (elem.type === 'ObjectExpression') {
      result.push(evalObjectExpression(elem))
    } else if (elem.type === 'ArrayExpression') {
      result.push(evalArrayExpression(elem))
    } else {
      throw new Error('Unsupported element type')
    }
  }
  return result
}

/**
 * Extract return type example from source, handling nested braces
 */
export function extractReturnExampleFromSource(source: string): string | null {
  let result = ''
  let depth = 0
  let hasContent = false

  for (let i = 0; i < source.length; i++) {
    const char = source[i]

    if (char === '{' || char === '[' || char === '(') {
      if (char === '{' && depth === 0 && hasContent) {
        // Found the function body opening brace
        break
      }
      depth++
      result += char
      hasContent = true
    } else if (char === '}' || char === ']' || char === ')') {
      depth--
      result += char
    } else if (!/\s/.test(char)) {
      result += char
      hasContent = true
    } else {
      result += char
    }
  }

  const trimmed = result.trim()
  return trimmed || null
}

/**
 * A literal union's FIRST member, or the text unchanged.
 *
 * Signature-test arguments are built with `new Function(\`return ${example}\`)()`, and a
 * literal union's source is valid JavaScript that means something else entirely:
 * `new Function("return 'yes' | 'no'")()` is **bitwise OR**, and evaluates to `0`. So
 * `function pick(x: 'yes' | 'no'): ''` was called as `pick(0)`, failed its own parameter
 * check, and reported
 *
 *     Function signature example is inconsistent:
 *       expected: "\"yes\" | \"no\"", actual: "number"
 *
 * — a hard failure of `tjs check`, and a THROW from plain `tjs(source)`, so the playground,
 * `tjs emit` and every programmatic consumer went with it. Numeric unions are wrong the
 * same way and more quietly: `1 | 2` evaluates to `3`.
 *
 * Literal unions are announced under Added in 0.13.0, and every example in
 * `TJS-SYNTAX.md` §Literal Unions omits a return annotation — which is exactly why
 * nothing caught it. The combination is what breaks, and the docs never showed it.
 *
 * Any member is a valid argument, so the first one is used. Split over the MASKED view so
 * a `|` inside a string (`'a|b' | 'c'`) is not a separator, and `||` is left alone.
 *
 * Collapse every literal union in `example` to its first member, at ANY depth.
 *
 * The first version only looked at depth 0, so a union nested inside an array or an object
 * was left intact and still evaluated as bitwise OR:
 *
 *     function tag(xs: ['yes' | 'no']): 1   ->  actual: "array of number"
 *     function cfg(o: { mode: 'a' | 'b' }): 1  ->  actual: "number"
 *
 * Literal unions are the headline 0.13.0 feature and putting one inside an array or an
 * options object is ordinary, so the shallow fix covered the demo case and not the real
 * one. Recursion is over the MASKED view, so a `|` inside a string stays data and `||`
 * is never a separator.
 */
function collapseUnions(example: string): string {
  const masked = maskLiterals(example)
  // Split at the OUTERMOST level first, then recurse into whatever the first member is.
  let depth = 0
  for (let i = 0; i < masked.length; i++) {
    const c = masked[i]
    if (c === '(' || c === '[' || c === '{') depth++
    else if (c === ')' || c === ']' || c === '}') depth--
    else if (
      c === '|' &&
      depth === 0 &&
      masked[i + 1] !== '|' &&
      masked[i - 1] !== '|'
    ) {
      return collapseUnions(example.slice(0, i).trim())
    }
  }
  // No top-level union: rebuild the value with each bracketed group collapsed in turn.
  let out = ''
  let i = 0
  while (i < masked.length) {
    const c = masked[i]
    if (c === '[' || c === '{' || c === '(') {
      const close = matchingBrace(masked, i)
      if (close === -1) {
        out += example.slice(i)
        break
      }
      // ELEMENT BY ELEMENT, not the bracket body as a whole.
      //
      // Passing the whole body back through `collapseUnions` meant the recursion found the
      // first depth-0 `|` *inside the container* and returned only what was left of it —
      // discarding every sibling after the union. Whether a file compiled depended on the
      // ORDER of its members:
      //
      //     function cfg(o: { mode: 'a' | 'b', other: 1 })   THREW
      //     function h(o:   { other: 1, mode: 'a' | 'b' })   passed
      //
      // and `['a' | 'b', 'c']` collapsed to a ONE-element array, so the signature test ran
      // against a shorter argument and passed while checking less than it claimed. That
      // silent half is the worse one, and it shipped in 0.13.0.
      //
      // Splitting at top level first means each element is collapsed in its own scope,
      // where a `|` really is that element's union. `splitTopLevel` masks literals, so a
      // comma inside a string does not split.
      const inner = example.slice(i + 1, close)
      out +=
        c +
        splitTopLevel(inner, ',').map(collapseUnions).join(',') +
        example[close]
      i = close + 1
      continue
    }
    out += example[i]
    i++
  }
  return out
}

/**
 * Extract parameter example values from params string
 */
function extractParamExamples(paramsStr: string): string[] {
  if (!paramsStr.trim()) return []

  const examples: string[] = []
  const params = splitTopLevelTrimmed(paramsStr)

  for (const param of params) {
    const trimmed = param.trim()

    // Rest parameter: ...name: [examples] — spread the array elements as individual args
    const restMatch = trimmed.match(/^\.\.\.(\w+)\s*[:=]\s*(\[.+\])$/)
    if (restMatch) {
      try {
        const arr = __lit(restMatch[2])
        if (Array.isArray(arr)) {
          for (const el of arr) {
            examples.push(JSON.stringify(el))
          }
        }
      } catch {
        // Can't parse — skip rest param examples
      }
      continue
    }

    // Bare rest param without type: ...name — skip (no example to use)
    if (trimmed.startsWith('...')) continue

    // Destructured object parameter: `{a: 2, b = 3}`.
    //
    // This used to fall through to the generic regex below, which matched from the first
    // member name and produced the un-evaluatable fragment `2, b = 3}` — `new Function`
    // threw, the enclosing `catch {}` swallowed it, and the function silently got NO
    // signature test. So the language's headline promise ("the annotation is the test")
    // quietly did not hold for the one parameter shape people destructure most.
    //
    // The call argument is built from REQUIRED members only. `:` members must be supplied;
    // `=` members are omitted so the generated call exercises their defaults — which is
    // the strictly stronger test, and not hypothetically so: it is exactly the path where a
    // corrupted `'hello,'` default was returning `'hello,  alice!'`.
    const objectPattern = trimmed.match(/^\{([\s\S]*)\}$/)
    if (objectPattern) {
      const supplied: string[] = []
      for (const member of splitTopLevelTrimmed(objectPattern[1])) {
        if (!member.trim()) continue
        const binding = splitMemberBinding(member)
        // Shorthand (`{a}`) or anything we can't read has no example, so there is no
        // argument to synthesize and no honest signature test to run.
        if (!binding) return []
        if (binding.op === ':')
          supplied.push(`${binding.name}: ${binding.value}`)
      }
      examples.push(`{${supplied.join(', ')}}`)
      continue
    }

    // Match: name: example or name = example (with optional safety markers)
    // Handle: (? name: example) or (! name: example)
    const match = trimmed.match(/(?:\(\s*[?!]\s*)?(\w+)\s*[:=]\s*(.+?)(?:\))?$/)
    if (match) {
      // A literal union's source evaluates as bitwise OR — see collapseUnions.
      examples.push(collapseUnions(match[2].trim()))
    } else {
      // No example value - can't run signature test
      return []
    }
  }

  return examples
}

/**
 * Read one destructured member as `name`, its binding operator, and its value.
 *
 * The operator has to be found at DEPTH ZERO on a literal-masked view, because both
 * characters occur freely inside a member's value: `a = { x: 1 }` binds with `=` despite
 * containing a colon, and `a: 'x = y'` binds with `:` despite containing an equals. Reading
 * whichever character appears first in the raw text gets both of those backwards.
 */
function splitMemberBinding(
  member: string
): { name: string; op: ':' | '='; value: string } | null {
  const masked = maskLiterals(member)
  let depth = 0

  for (let i = 0; i < masked.length; i++) {
    const char = masked[i]
    if (char === '(' || char === '[' || char === '{') depth++
    else if (char === ')' || char === ']' || char === '}') depth--
    else if (depth === 0 && (char === ':' || char === '=')) {
      const name = member.slice(0, i).trim()
      if (!/^\w+$/.test(name)) return null
      return {
        name,
        op: char as ':' | '=',
        value: member.slice(i + 1).trim(),
      }
    }
  }

  return null
}

/**
 * Compile WASM blocks and generate bootstrap code that embeds the compiled bytes
 * and instantiates them on load.
 */

/**
 * Serialise a value as JAVASCRIPT SOURCE, not as JSON.
 *
 * These call sites are generating code — the value has to come back as a literal the engine
 * will re-evaluate. `JSON.stringify` was standing in for that and mostly works, but it
 * THROWS on a BigInt rather than skipping it, so a single `x: 0n` example anywhere in a file
 * took down the whole transpile with "JSON.stringify cannot serialize BigInt": no file, no
 * line, no indication of which annotation was responsible.
 *
 * BigInt is the only value JSON cannot represent that TJS can legitimately hold as an
 * example, so it is the only special case; everything else defers to JSON.stringify, which
 * emits valid JS literal syntax for it.
 */
function toSourceLiteral(value: unknown): string {
  if (typeof value === 'bigint') return `${value}n`
  if (Array.isArray(value)) {
    return `[${value.map(toSourceLiteral).join(', ')}]`
  }
  if (value && typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>).map(
      ([k, v]) => `${JSON.stringify(k)}: ${toSourceLiteral(v)}`
    )
    return `{${entries.join(', ')}}`
  }
  return JSON.stringify(value)
}
